void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord.xy / iResolution.xy;

    // Animate gradient movement
    float t = iTime * 0.8;
    float sinTime = sin(t);
    float cosTime = cos(t);

    // Define customizable colors
    vec3 color1 = vec3(0.9, 0.2, 0.3);
    vec3 color2 = vec3(0.2, 0.4, 0.9);
    vec3 color3 = vec3(0.9, 0.8, 0.2);
    vec3 color4 = vec3(0.3, 0.9, 0.6);

    // Background color cycles through the defined colors over a different time interval
    float bgT = iTime * 0.5;
    vec3 backgroundColor = mix(mix(color1, color2, sin(bgT) * 0.5 + 0.5), mix(color3, color4, cos(bgT) * 0.5 + 0.5), sin(bgT * 0.5) * 0.5 + 0.5);

    // Create an oval-shaped color distribution over fullscreen
    vec2 ovalUV = vec2((uv.x - 0.5) * 1.5, uv.y - 0.5);
    float distanceFromCenter = length(ovalUV);
    float ovalGradient = smoothstep(1.2, 0.2, distanceFromCenter);

    // Gradient interpolation with radial influence
    vec3 gradient1 = mix(color1, color2, smoothstep(0.5, 1.0, uv.y + sinTime * 0.2));
    vec3 gradient2 = mix(color3, color4, smoothstep(0.5, 1.0, uv.x + cosTime * 0.2));

    // Blend the gradients together
    vec3 finalColor = mix(gradient1, gradient2, 0.05 + 1.0 * sin(uv.x * 2.14 + sin(t)));

    // Apply the oval effect by modulating color intensity while keeping fullscreen
    finalColor = mix(backgroundColor, finalColor, ovalGradient);

    // Increase saturation by boosting color contrast (adjust the factor as needed)
    float saturation = 1.6; // 1.0 is the OG saturation, increase for stronger saturation
    finalColor = mix(vec3(dot(finalColor, vec3(0.299, 0.587, 0.114))), finalColor, saturation);

    fragColor = vec4(finalColor, 1.0);
}
